int CBinaryInputStream::CbRead(int cb, void *pv)
{
    int cbLeft = cb;
    byte *pb = (byte *)pv;

    if (m_cb < 0)
        return 0;

    while (cbLeft > 0)
    {
        Refill();
        if (m_cb == 0)
        {
            m_cb = -1;
            break;
        }

        int cbCopy = (cbLeft < m_cb) ? cbLeft : m_cb;

        if (pb)
        {
            CopyAb(pb, m_pb, cbCopy);
            pb += cbCopy;
        }

        m_pb += cbCopy;
        m_cb -= cbCopy;
        cbLeft -= cbCopy;
    }

    return cb - cbLeft;
}

