/* LZSS: 8K window, flag byte per 8 tokens (bit set = literal), references are
 * 13-bit offset + 3-bit length (copies length + 3 bytes). */

/** @sly2-annot addr=0x1179F0
 * Purpose: not written up yet; only the symbol name (pre-existing / Sly 1-derived) describes it.
 * Confidence: mid (draft) - evidence: pre-existing symbol name only; behaviour not reviewed
 * See: docs/engine/core-library.md#4-binary-input-streams-and-cd,
 *   docs/formats/compression-lzss.md#compression-whole-file-lzss, docs/formats/world-file.md#1-container
 * @end-sly2-annot */
void CBinaryInputStream::Decompress()
{
    int cbOut = 0;
    byte *pbOut = m_pbDecomp;
    int cbIn = m_cbRaw;
    byte *pbIn = m_pbRaw;
    int grf = m_grfDecomp;

    if (m_cbPending > 0)
    {
        memcpy(pbOut, pbOut + 0x2000, m_cbPending);
        cbOut = m_cbPending;
    }

    int grfMark = 0xFF00;   /* loop-hoisted constant in the original */
    while (cbOut < 0x2000)
    {
        grf >>= 1;
        if (!(grf & 0x100))
        {
            if (--cbIn < 0)
            {
                Fill();
                if (m_cbRaw <= 0)
                    break;
                pbIn = m_pbRaw;
                cbIn = m_cbRaw - 1;
            }
            grf = *pbIn++ + grfMark;
        }

        if (--cbIn < 0)
        {
            Fill();
            if (m_cbRaw <= 0)
                break;
            pbIn = m_pbRaw;
            cbIn = m_cbRaw - 1;
        }
        int b = *pbIn++;

        if (grf & 1)
        {
            pbOut[cbOut++] = b;
        }
        else
        {
            if (--cbIn < 0)
            {
                Fill();
                pbIn = m_pbRaw;
                cbIn = m_cbRaw - 1;
            }
            int v = b + (*pbIn++ << 8);
            int cb = (v >> 13) + 2;
            int ib = v & 0x1FFF;
            for (; cb >= 0; cb--)
            {
                pbOut[cbOut++] = pbOut[ib++ & 0x1FFF];
            }
        }
    }

    m_pb = pbOut;
    if (cbOut >= 0x2000)
    {
        m_cb = 0x2000;
        m_cbPending = cbOut - 0x2000;
    }
    else
    {
        m_cb = cbOut;
        m_cbPending = 0;
    }
    m_pbRaw = pbIn;
    m_cbRaw = cbIn;
    m_grfDecomp = grf;
}

